parameters.value:
=Analiza el sentimiento del siguiente texto en español. Responde ÚNICAMENTE con un JSON válido:

Texto: {{ $json.texto }}

Formato de respuesta:
{
  "sentimiento": "positivo|negativo|neutral",
  "puntuacion": 0.0-1.0,
  "emociones": ["alegría", "tristeza", ...],
  "entidades": ["producto", "servicio", ...],
  "resumen": "breve resumen del análisis"
}

parameters.jsCode:
try {
  const result = JSON.parse($input.item.json.response);
  return { json: { ...result, texto_original: $input.item.json.response, timestamp: new Date().toISOString() } };
} catch(e) {
  return { json: { sentimiento: 'desconocido', puntuacion: 0, texto: $input.item.json.response, timestamp: new Date().toISOString() } };
}
